findings.suggested_fix:
Add an ownership check for the orders being sorted. For example:

@orders_bp.route("/sorted", methods=["GET"])
@require_role("manager")
def sorted_orders():
    sort_by = request.args.get("sort_by", "created_at")
    session = get_session()
    user_id = current_user.id
    rows = session.execute(
        text(f"SELECT id, user_id, status, total FROM orders WHERE user_id = :user_id ORDER BY {sort_by}")
    ).params(user_id=user_id)
    return jsonify([dict(r._mapping) for r in rows])
